export const DOCS_MORE = [
  { slug: "scheme-ii-crs-explained", kind: "scheme", title: "Compulsory Registration Scheme (Scheme-II / CRS)", body: "Scheme-II makes registration with BIS compulsory before a notified product can be manufactured, imported or sold in India. Unlike Scheme-I it has no factory-quality audit up front: BIS tests samples in a recognised laboratory and, on conformity, grants an R-number registration valid for two years. The Standard Mark alone is not permitted — the R-number must be printed on the product and its packaging.", bodyHi: "योजना-II के अंतर्गत अधिसूचित उत्पाद के निर्माण, आयात या विक्रय से पूर्व BIS में पंजीकरण अनिवार्य है। योजना-I के विपरीत इसमें प्रारंभिक कारखाना audit नहीं होता: BIS मान्यता प्राप्त प्रयोगशाला में नमूनों का परीक्षण करता है और अनुरूपता पर दो वर्ष के लिए R-संख्या प्रदान करता है।", keywords: ["crs", "scheme ii", "scheme 2", "r number", "registration", "compulsory"], refs: ["IS 13252-1:2010"] },
  { slug: "process-surveillance-after-certification", kind: "process", title: "What happens after you get a licence — surveillance", body: "Certification is not a one-time event. BIS carries out unannounced surveillance visits and draws samples from the factory or the market for independent testing. Adverse results can lead to stoppage of marking, suspension or cancellation of the licence. Licensees must maintain test records, calibrate equipment and report any change of raw material, process or premises.", bodyHi: "प्रमाणन एक बार की घटना नहीं है। BIS बिना पूर्व सूचना के निरीक्षण करता है और कारखाने या बाज़ार से नमूने लेकर स्वतंत्र परीक्षण करता है। प्रतिकूल परिणाम पर अंकन रोकने, लाइसेंस निलंबित या रद्द करने की कार्यवाही हो सकती है।", keywords: ["surveillance", "inspection", "audit", "sample", "suspension", "monitoring"], refs: [] },
  { slug: "fees-certification-cost-heads", kind: "fees", title: "Heads of cost in BIS certification", body: "Certification cost is built from separate heads: application fee, marking fee (per unit or per declared value), annual licence fee, testing charges for samples, and out-of-pocket expenses for factory visits. For foreign applicants there are additional charges for travel and a nominating agent. Fees are prescribed in the relevant scheme regulations and are revised periodically.", bodyHi: "प्रमाणन लागत अलग-अलग मदों से बनती है: आवेदन शुल्क, अंकन शुल्क, वार्षिक लाइसेंस शुल्क, नमूना परीक्षण शुल्क तथा कारखाना भ्रमण का व्यय। विदेशी आवेदकों के लिए यात्रा व नामांकित एजेंट का अतिरिक्त शुल्क लागू होता है।", keywords: ["fees", "cost", "charges", "marking fee", "licence fee", "शुल्क"], refs: [] },
  { slug: "labs-recognised-laboratory-scheme", kind: "labs", title: "BIS recognised laboratories vs BIS laboratories", body: "BIS tests samples either in its own laboratories or in laboratories recognised under the Laboratory Recognition Scheme. A recognised laboratory must be accredited to ISO/IEC 17025 for the relevant tests and keeps its scope under surveillance. For most manufacturers the practical difference is turnaround time and location — a recognised laboratory near the factory shortens the certification cycle.", bodyHi: "BIS नमूनों का परीक्षण अपनी प्रयोगशालाओं में या प्रयोगशाला मान्यता योजना के अंतर्गत मान्यता प्राप्त प्रयोगशालाओं में करता है। मान्यता प्राप्त प्रयोगशाला को संबंधित परीक्षणों हेतु ISO/IEC 17025 अनुरूप मान्यता आवश्यक है।", keywords: ["laboratory", "lab", "recognition", "iso 17025", "testing", "प्रयोगशाला"], refs: [] },
  { slug: "concept-what-is-a-qco", kind: "concept", title: "Quality Control Orders — the legal hook behind mandatory marks", body: "A Quality Control Order is issued by a Ministry under the BIS Act, 2016. It names a product and the Indian Standard it must conform to, and prohibits manufacture, sale, import or stocking without the Standard Mark under a valid licence. Once a QCO is notified, the certification it points to stops being voluntary. QCOs usually give industry a transition period before they come into force.", bodyHi: "गुणवत्ता नियंत्रण आदेश मंत्रालय द्वारा BIS अधिनियम, 2016 के अंतर्गत जारी किया जाता है। इसमें उत्पाद व संबंधित भारतीय मानक निर्दिष्ट होता है और वैध लाइसेंस के बिना निर्माण, विक्रय, आयात या भंडारण पर रोक लगती है।", keywords: ["qco", "quality control order", "mandatory", "notification", "ministry", "गुणवत्ता"], refs: [] },
  { slug: "process-foreign-manufacturer-certification", kind: "process", title: "Certification route for foreign manufacturers", body: "A manufacturer with no factory in India applies under the relevant Scheme for foreign manufacturers. BIS requires an authorised Indian representative, auditing of the overseas factory by a BIS team, and payment of travel and other out-of-pocket costs. The licence is held against the overseas premises; the Indian representative is answerable for compliance in the Indian market.", bodyHi: "भारत में कारखाना न रखने वाला निर्माता विदेशी निर्माताओं के लिए निर्धारित योजना के अंतर्गत आवेदन करता है। BIS अधिकृत भारतीय प्रतिनिधि, विदेशी कारखाने का BIS दल द्वारा audit तथा यात्रा व्यय का भुगतान अपेक्षित करता है।", keywords: ["foreign manufacturer", "import", "fmc", "authorised representative", "overseas", "आयात"], refs: [] },
  { slug: "hallmark-huid-how-to-verify", kind: "hallmark", title: "Verifying a hallmark and its HUID", body: "Every hallmarked gold article carries the BIS standard mark, the fineness grade such as 22K916, the assaying and hallmarking centre's mark and a six-character alphanumeric HUID. The HUID is unique to the article and can be checked in the BIS HUID search or the BIS CARE app. A hallmark without an HUID is not a valid hallmark under the current scheme.", bodyHi: "प्रत्येक हॉलमार्कित स्वर्ण वस्तु पर BIS मानक चिह्न, शुद्धता ग्रेड जैसे 22K916, असेइंग एवं हॉलमार्किंग केन्द्र का चिह्न तथा छह अक्षरों का HUID अंकित होता है। HUID वस्तु-विशिष्ट होता है और BIS CARE ऐप से जाँचा जा सकता है।", keywords: ["huid", "hallmark", "verify", "care app", "fineness", "हॉलमार्क"], refs: ["IS 1417:2016"] },
  { slug: "consumer-report-misuse-of-standard-mark", kind: "consumer", title: "How to report misuse of the ISI mark or hallmark", body: "If a product carries an ISI mark, R-number or hallmark that appears fake or does not check out, you can complain to BIS through the BIS CARE app, the online grievance form or the nearest BIS branch office. Keep the bill, a photograph of the marking and the packaging. BIS treats misuse of the Standard Mark as an offence under the BIS Act, 2016 and can launch search and seizure.", bodyHi: "यदि किसी उत्पाद पर ISI चिह्न, R-संख्या या हॉलमार्क नकली प्रतीत हो या जाँच में न मिले, तो आप BIS CARE ऐप, ऑनलाइन शिकायत फ़ॉर्म या निकटतम BIS शाखा में शिकायत कर सकते हैं। बिल, अंकन का फ़ोटो व पैकेजिंग सुरक्षित रखें।", keywords: ["complaint", "misuse", "fake isi", "grievance", "bis care", "शिकायत"], refs: [] },
];

export const DOCS_WAVE3 = [
  { slug: "faq-are-imports-covered-by-bis", kind: "faq", title: "FAQ — does BIS certification apply to imported goods?", body: "Yes. When a product is covered by a QCO or by the Compulsory Registration Scheme, the goods must be certified before they are imported, not merely before they are sold. Customs clearance looks for the Standard Mark or R-number. The foreign manufacturer has to hold the licence or registration in its own name before shipment.", bodyHi: "हाँ। जब उत्पाद किसी QCO या अनिवार्य पंजीकरण योजना के अंतर्गत आता है, तो आयात से पूर्व प्रमाणन आवश्यक है — केवल विक्रय से पूर्व नहीं। सीमा शुल्क निकासी में मानक चिह्न या R-संख्या की जाँच होती है।", keywords: ["import", "customs", "shipment", "faq", "qco", "आयात"], refs: [] },
  { slug: "faq-licence-validity-and-renewal", kind: "faq", title: "FAQ — how long does a BIS licence last?", body: "A Scheme-I licence is granted for an initial period of one to two years and is renewed on application, subject to continued conformity in surveillance. A CRS registration runs for two years and is renewed the same way. Renewal applications are best filed well before expiry; if a licence lapses the marking must stop immediately, and goods made in the lapsed period cannot be marked retrospectively.", bodyHi: "योजना-I का लाइसेंस प्रारंभ में एक से दो वर्ष के लिए दिया जाता है और आवेदन पर नवीनीकृत किया जाता है, बशर्ते निरीक्षण में अनुरूपता बनी रहे। CRS पंजीकरण दो वर्ष के लिए होता है। नवीनीकरण का आवेदन समय से पूर्व करना उचित है।", keywords: ["renewal", "validity", "expiry", "licence", "faq", "नवीनीकरण"], refs: [] },
  { slug: "faq-is-vs-iso-numbering", kind: "faq", title: "FAQ — what do IS, IS/ISO and IS/IEC prefixes mean?", body: "IS means an Indian Standard developed by BIS. IS/ISO means BIS has adopted an ISO standard as an Indian Standard, usually identically. IS/IEC means an IEC electrical standard adopted the same way. The number after the hyphen is the part, so IS 302-2-15 is Part 2, Section 15 of IS 302. The year after the colon is the edition year, which is what you should quote on a test report.", bodyHi: "IS का अर्थ है BIS द्वारा विकसित भारतीय मानक। IS/ISO का अर्थ है BIS ने किसी ISO मानक को भारतीय मानक के रूप में अपनाया है। IS/IEC में IEC के विद्युत मानक को अपनाया गया है। हाइफ़न के बाद की संख्या भाग बताती है।", keywords: ["is", "iso", "iec", "numbering", "prefix", "faq"], refs: [] },
  { slug: "consumer-read-a-standard-number", kind: "consumer", title: "Reading a standard number on a product", body: "A marking such as IS 1786:2008 Fe 500D CM/L-7600112290 tells you four things: the standard, the edition year, the grade and the licence number. Quote all four when you raise a query. The licence number is the one to verify — it tells you the mark belongs to a real, current licence rather than a printed imitation.", bodyHi: "IS 1786:2008 Fe 500D CM/L-7600112290 जैसे अंकन से चार बातें पता चलती हैं: मानक, संस्करण वर्ष, ग्रेड और लाइसेंस संख्या। शिकायत करते समय चारों उद्धृत करें। लाइसेंस संख्या की जाँच सबसे महत्वपूर्ण है।", keywords: ["marking", "licence number", "grade", "reading", "label", "अंकन"], refs: [] },
  { slug: "consumer-check-before-buying-cement", kind: "consumer", title: "What to check before buying cement", body: "Check the grade on the bag (OPC 33, 43, 53, PPC or PSC), the IS number it conforms to, the ISI mark with licence number, the net quantity, the manufacturing week and the best-before date. Cement loses strength with age and moisture, so buy a recent batch and store it off the floor, away from walls, under a waterproof cover.", bodyHi: "बोरी पर ग्रेड (OPC 33, 43, 53, PPC या PSC), अनुरूप IS संख्या, लाइसेंस संख्या सहित ISI चिह्न, शुद्ध मात्रा, निर्माण सप्ताह व उपयोग-अंतिम तिथि देखें। सीमेंट समय व नमी से कमज़ोर होता है, अतः ताज़ा बैच खरीदें।", keywords: ["cement", "opc", "ppc", "buying", "bag", "checklist", "सीमेंट"], refs: ["IS 269:2015"] },
  { slug: "consumer-check-before-buying-steel", kind: "consumer", title: "What to check before buying TMT bars", body: "Look for the grade (Fe 500, Fe 500D, Fe 550D), the IS number, the ISI mark and the licence number on the bundle tag. Ribs should be uniform and free of loose rust scale. Ask the dealer for the manufacturer's test certificate for that heat or batch, and check the weight against the theoretical section weight for the diameter.", bodyHi: "गठ्ठरी के टैग पर ग्रेड (Fe 500, Fe 500D, Fe 550D), IS संख्या, ISI चिह्न व लाइसेंस संख्या देखें। रिब्स समान होने चाहिएँ तथा ढीली ज़ंग की परत नहीं होनी चाहिए। डीलर से उस बैच का परीक्षण प्रमाणपत्र माँगें।", keywords: ["tmt", "rebar", "saria", "buying", "grade", "checklist", "सरिया"], refs: ["IS 1786:2008"] },
  { slug: "process-complaint-redressal-bis", kind: "process", title: "Complaint redressal against a certified product", body: "A complaint about the quality of a certified product can be filed with BIS, which may draw a sample from the market and get it tested against the standard. If the sample fails, action is taken against the licensee. Complaints about price, delivery or warranty are consumer-protection matters and go to the consumer forum, not to BIS.", bodyHi: "प्रमाणित उत्पाद की गुणवत्ता संबंधी शिकायत BIS में दर्ज की जा सकती है, जो बाज़ार से नमूना लेकर मानक के अनुरूप परीक्षण कर सकता है। नमूना विफल होने पर लाइसेंसधारी के विरुद्ध कार्यवाही होती है। मूल्य या वारंटी विवाद उपभोक्ता मंच के अंतर्गत आते हैं।", keywords: ["complaint", "redressal", "sample", "grievance", "quality", "शिकायत"], refs: [] },
  { slug: "concept-standard-mark-logos", kind: "concept", title: "The marks you will see: ISI, CRS, hallmark, HUID", body: "The ISI mark is used under Scheme-I product certification and always accompanies a CM/L- licence number. The CRS registration is shown by the Standard Mark with an R-number. Gold and silver articles carry the hallmark consisting of the BIS mark, fineness grade, AHC mark and HUID. No other mark purporting to be a BIS mark is valid.", bodyHi: "ISI चिह्न योजना-I उत्पाद प्रमाणन के अंतर्गत प्रयुक्त होता है और इसके साथ CM/L- लाइसेंस संख्या होती है। CRS पंजीकरण में मानक चिह्न के साथ R-संख्या होती है। स्वर्ण व रजत वस्तुओं पर हॉलमार्क होता है।", keywords: ["isi", "crs", "hallmark", "huid", "logos", "mark", "चिह्न"], refs: [] },
];

