/** Seeds all content tables. `dbOverride` lets the pglite bootstrap pass its
 * own connection (avoiding a circular module reference at startup). */
export async function seed(dbOverride?: typeof db) {
  const target = dbOverride ?? db;
  console.log("Seeding PRAMAAN knowledge base…");
  await target.delete(standards);
  await target.delete(knowledgeDocs);
  await target.delete(labs);
  await target.delete(licences);

  const ALL_STANDARDS = [
    ...STD,
    ...STD_MORE,
    ...STD_WAVE3,
    ...STD_WAVE4,
    ...STD_WAVE5,
    ...STD_WAVE6,
    ...STD_WAVE7,
    ...STD_WAVE8,
    ...STD_WAVE9,
    ...STD_WAVE10,
    ...STD_WAVE11,
    ...STD_WAVE12,
    ...STD_WAVE13,
    ...STD_WAVE14,
    ...STD_WAVE15,
    ...STD_WAVE16,
  ];
  const ALL_DOCS = [...DOCS, ...DOCS_MORE, ...DOCS_WAVE3];
  const ALL_LABS = [
    ...LABS,
    ...LABS_MORE,
    ...LABS_WAVE3,
    ...LABS_NETWORK_UNIQUE,
  ];
  const ALL_LICENCES = [...LICENCES, ...LICENCES_MORE, ...LICENCES_WAVE3];

  /* insert in chunks — the expanded catalogue is ~2000 rows */
  const CHUNK = 250;
  for (let i = 0; i < ALL_STANDARDS.length; i += CHUNK)
    await target.insert(standards).values(ALL_STANDARDS.slice(i, i + CHUNK) as never);
  await target.insert(knowledgeDocs).values(ALL_DOCS as never);
  for (let i = 0; i < ALL_LABS.length; i += CHUNK)
    await target.insert(labs).values(ALL_LABS.slice(i, i + CHUNK) as never);
  await target.insert(licences).values(ALL_LICENCES as never);

  /* complaints are demo rows — replace wholesale so re-seeding is idempotent */
  await target.delete(complaints);
  await target.insert(complaints).values(COMPLAINTS as never);

  console.log(
    `Seeded ${ALL_STANDARDS.length} standards, ${ALL_DOCS.length} docs, ` +
      `${ALL_LABS.length} labs, ${ALL_LICENCES.length} licences, ${COMPLAINTS.length} complaints.`,
  );
}

/* Importing this module (e.g. from scripts/validate-data.ts) must NOT seed. */
if (process.argv[1]?.endsWith("seed.ts")) {
  seed()
    .then(() => process.exit(0))
    .catch((e) => {
      console.error(e);
      process.exit(1);
    });
}
